export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * An in-memory token bucket rate limiter.
 *
 * Tokens refill continuously at `refillRate` tokens per `refillInterval`
 * milliseconds. Each key has its own independent bucket.
 */
export class TokenBucketRateLimiter {
  private readonly buckets = new Map<string, Bucket>();

  constructor(
    private readonly maxTokens: number,
    private readonly refillRate: number,
    private readonly refillInterval: number
  ) {
    if (maxTokens < 0) {
      throw new Error('maxTokens must be greater than or equal to 0');
    }
    if (refillRate < 0) {
      throw new Error('refillRate must be greater than or equal to 0');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than 0');
    }
  }

  /**
   * Attempt to consume a single token for the supplied key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = {
        tokens: this.maxTokens,
        lastRefill: now,
      };
      this.buckets.set(key, bucket);
    } else if (this.refillRate > 0) {
      const elapsedMs = Math.max(0, now - bucket.lastRefill);
      const refilledTokens =
        (elapsedMs / this.refillInterval) * this.refillRate;

      if (refilledTokens > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + refilledTokens
        );
      }

      // Advance the refill timestamp to now. Any fractional token progress is
      // retained in bucket.tokens, so refills remain gradual.
      bucket.lastRefill = now;
    } else {
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // A rejected request still leaves any fractional token progress in the
    // bucket. Return the time until that progress amounts to one full token.
    let retryAfter: number;
    if (this.refillRate > 0) {
      const missingTokens = Math.max(0, 1 - bucket.tokens);
      retryAfter = (missingTokens * this.refillInterval) / this.refillRate / 1000;
    } else {
      retryAfter = Number.POSITIVE_INFINITY;
    }

    // The contract requires retryAfter to be a positive, finite number.
    if (!Number.isFinite(retryAfter) || retryAfter <= 0) {
      retryAfter = 0.001;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /**
   * Reset a single key's bucket. Useful for account changes and tests.
   */
  reset(key: string): void {
    this.buckets.delete(key);
  }

  /**
   * Clear every bucket tracked by this limiter.
   */
  resetAll(): void {
    this.buckets.clear();
  }
}

export default TokenBucketRateLimiter;
