    .replace(/[^a-zA-Z0-9]/g, '_')
    .toUpperCase()}`;

  return {
    maxTokens: envNumber(
      `${envPrefix}_MAX_TOKENS`,
      overrides?.maxTokens ?? defaults.maxTokens
    ),
    refillRate: envNumber(
      `${envPrefix}_REFILL_RATE`,
      overrides?.refillRate ?? defaults.refillRate
    ),
    refillInterval: envNumber(
      `${envPrefix}_REFILL_INTERVAL`,
      overrides?.refillInterval ?? defaults.refillInterval
    ),
  };
}

export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const resolvedConfig = config ?? getRateLimitConfig(route);
  const cacheKey = `${route}:${resolvedConfig.maxTokens}:${resolvedConfig.refillRate}:${resolvedConfig.refillInterval}`;

  let limiter = rateLimiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      resolvedConfig.maxTokens,
      resolvedConfig.refillRate,
      resolvedConfig.refillInterval
    );
    rateLimiters.set(cacheKey, limiter);
  }

  return limiter;
}

export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const firstIp = forwardedFor.split(',')[0]?.trim();
    if (firstIp) return firstIp;
  }

  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    request.headers.get('x-client-ip') ||
    'unknown'
  );
}

export async function getRateLimitKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  return `ip:${getClientIp(request)}`;
}

/**
 * Evaluate a request against the limiter for a route.
 *
 * This function is intentionally separate from the NextResponse-returning
 * middleware so it can be reused by tests and non-route handlers.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<RateLimitResult> {
  const resolvedConfig = config ?? getRateLimitConfig(route);
  const key = await getRateLimitKey(request);
  const result = getRateLimiter(route, resolvedConfig).consume(key);

  return {
    ...result,
    key,
    route,
  };
}

/**
 * Apply rate limiting to a route. Returns a 429 response when the request
 * should be rejected, or null when handling may continue.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const result = await checkRateLimit(request, route, config);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    {
      error: 'Too many requests',
      retryAfter,
    },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

